class TestTokenGeneration:
    """Validate token creation semantics."""

    def test_create_token_returns_jwt_string(self, auth_manager, valid_agent):
        """Token must be a non-empty string with three JWT segments."""
        token = auth_manager.create_token(valid_agent)
        assert isinstance(token, str)
        assert len(token.split(".")) == 3

    def test_create_token_contains_expected_claims(self, auth_manager, valid_agent):
        """Decoded token must contain agent_id, role, permissions, jti, iat, exp."""
        token = auth_manager.create_token(valid_agent)
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
        assert payload["agent_id"] == "agent-001"
        assert payload["role"] == "worker"
        assert payload["permissions"] == ["read", "write", "execute"]
        assert "jti" in payload
        assert "iat" in payload
        assert "exp" in payload

    def test_create_token_expiry_window(self, auth_manager, valid_agent):
        """Expiry must be ACCESS_TOKEN_EXPIRE_MINUTES from issuance."""
        before = datetime.now(timezone.utc)
        token = auth_manager.create_token(valid_agent)
        after = datetime.now(timezone.utc)
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
        exp = datetime.fromtimestamp(payload["exp"], tz=timezone.utc)
        expected_min = before + timedelta(minutes=ACCESS_TOKEN_EXPIRE_MINUTES)
        expected_max = after + timedelta(minutes=ACCESS_TOKEN_EXPIRE_MINUTES)
        assert expected_min <= exp <= expected_max

    def test_create_token_unique_jti(self, auth_manager, valid_agent):
        """Each token must have a unique jti claim."""
        token1 = auth_manager.create_token(valid_agent)
        token2 = auth_manager.create_token(valid_agent)
        payload1 = jwt.decode(token1, SECRET_KEY, algorithms=[ALGORITHM])
        payload2 = jwt.decode(token2, SECRET_KEY, algorithms=[ALGORITHM])
        assert payload1["jti"] != payload2["jti"]

    def test_create_token_iat_is_recent(self, auth_manager, valid_agent):
        """iat must be close to current time."""
        before = int(time.time())
        token = auth_manager.create_token(valid_agent)
        after = int(time.time())
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
        assert before <= payload["iat"] <= after


