class TestTokenVerification:
    """Validate token verification and rejection paths."""

    def test_verify_valid_token(self, auth_manager, valid_token, valid_agent):
        """Valid token must decode to matching identity."""
        identity = auth_manager.verify_token(valid_token)
        assert identity.agent_id == valid_agent.agent_id
        assert identity.role == valid_agent.role
        assert identity.permissions == valid_agent.permissions

    def test_verify_expired_token(self, auth_manager, valid_agent):
        """Expired token must raise AuthenticationError with EXPIRED code."""
        with patch("swarm_security.auth.datetime") as mock_dt:
            mock_dt.now.return_value = datetime(2020, 1, 1, tzinfo=timezone.utc)
            mock_dt.timedelta = timedelta
            token = auth_manager.create_token(valid_agent)
        with pytest.raises(AuthenticationError) as exc_info:
            auth_manager.verify_token(token)
        assert exc_info.value.code == "TOKEN_EXPIRED"

    def test_verify_malformed_token(self, auth_manager):
        """Malformed token must raise AuthenticationError with INVALID code."""
        with pytest.raises(AuthenticationError) as exc_info:
            auth_manager.verify_token("not.a.jwt")
        assert exc_info.value.code == "INVALID_TOKEN"

    def test_verify_wrong_algorithm(self, auth_manager, valid_agent):
        """Token signed with wrong algorithm must be rejected."""
        token = jwt.encode(
            {"agent_id": valid_agent.agent_id, "role": valid_agent.role},
            SECRET_KEY,
            algorithm="HS512"
        )
        with pytest.raises(AuthenticationError) as exc_info:
            auth_manager.verify_token(token)
        assert exc_info.value.code == "INVALID_TOKEN"

    def test_verify_tampered_token(self, auth_manager, valid_token):
        """Tampered payload must be rejected."""
        parts = valid_token.split(".")
        # Flip a character in the payload segment
        tampered_payload = parts[1][:-1] + ("A" if parts[1][-1] != "A" else "B")
        tampered_token = f"{parts[0]}.{tampered_payload}.{parts[2]}"
        with pytest.raises(AuthenticationError) as exc_info:
            auth_manager.verify_token(tampered_token)
        assert exc_info.value.code == "INVALID_TOKEN"

    def test_verify_missing_required_claims(self, auth_manager):
        """Token missing required claims must be rejected."""
        token = jwt.encode({"sub": "test"}, SECRET_KEY, algorithm=ALGORITHM)
        with pytest.raises(AuthenticationError) as exc_info:
            auth_manager.verify_token(token)
        assert exc_info.value.code == "INVALID_TOKEN"


