class TestRequireAuthDecorator:
    """Validate the require_auth decorator behavior."""

    def test_authorized_access(self, auth_manager, valid_token, valid_agent):
        """Decorated function must execute with valid token."""
        @require_auth
        def protected_endpoint(identity):
            return {"agent_id": identity.agent_id}

        result = protected_endpoint(
            token=valid_token,
            auth_manager=auth_manager
        )
        assert result == {"agent_id": valid_agent.agent_id}

    def test_missing_token(self, auth_manager):
        """Missing token must raise AuthenticationError."""
        @require_auth
        def protected_endpoint(identity):
            return {"agent_id": identity.agent_id}

        with pytest.raises(AuthenticationError) as exc_info:
            protected_endpoint(auth_manager=auth_manager)
        assert exc_info.value.code == "MISSING_TOKEN"

    def test_invalid_token(self, auth_manager):
        """Invalid token must raise AuthenticationError."""
        @require_auth
        def protected_endpoint(identity):
            return {"agent_id": identity.agent_id}

        with pytest.raises(AuthenticationError) as exc_info:
            protected_endpoint(token="invalid.token.value", auth_manager=auth_manager)
        assert exc_info.value.code == "INVALID_TOKEN"

    def test_unauthorized_permission(self, auth_manager, valid_token):
        """Missing required permission must raise AuthenticationError."""
        @require_auth(permissions=["admin"])
        def admin_endpoint(identity):
            return {"agent_id": identity.agent_id}

        with pytest.raises(AuthenticationError) as exc_info:
            admin_endpoint(token=valid_token, auth_manager=auth_manager)
        assert exc_info.value.code == "INSUFFICIENT_PERMISSIONS"

    def test_decorator_preserves_metadata(self):
        """Decorator must preserve function name and docstring."""
        @require_auth
        def documented_endpoint(identity):
            """Docstring preserved."""
            return identity

        assert documented_endpoint.__name__ == "documented_endpoint"
        assert documented_endpoint.__doc__ == "Docstring preserved."


