class TestTokenPropertyBased:
    """Property-based validation of token round-trip integrity."""

    @given(
        agent_id=st.text(min_size=1, max_size=64),
        role=st.text(min_size=1, max_size=32),
        permissions=st.lists(st.text(min_size=1, max_size=16), max_size=10)
    )
    def test_token_roundtrip_preserves_identity(self, agent_id, role, permissions):
        """Any valid identity must survive token round-trip."""
        auth_manager = AuthManager()
        identity = AgentIdentity(
            agent_id=agent_id,
            role=role,
            permissions=permissions
        )
        token = auth_manager.create_token(identity)
        decoded = auth_manager.verify_token(token)
        assert decoded.agent_id == agent_id
        assert decoded.role == role
        assert decoded.permissions == permissions

    @given(
        agent_id=st.text(min_size=1, max_size=64),
        role=st.text(min_size=1, max_size=32)
    )
    def test_token_always_has_required_claims(self, agent_id, role):
        """Every generated token must contain all required claims."""
        auth_manager = AuthManager()
        identity = AgentIdentity(agent_id=agent_id, role=role)
        token = auth_manager.create_token(identity)
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
        for claim in ["agent_id", "role", "permissions", "jti", "iat", "exp"]:
            assert claim in payload

    @given(st.integers(min_value=1, max_value=1440))
    def test_token_expiry_matches_config(self, minutes):
        """Expiry must respect configured duration."""
        with patch.object(AuthManager, "token_expire_minutes", minutes):
            auth_manager = AuthManager()
            identity = AgentIdentity(agent_id="prop-test")
            token = auth_manager.create_token(identity)
            payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
            iat = payload["iat"]
            exp = payload["exp"]
            assert exp - iat == minutes * 60


