# Concurrency / Race Condition Tests
# =============================================================================

class TestConcurrency:
    """Validate thread-safety of token generation."""

    def test_concurrent_token_generation_unique_jti(self, auth_manager, valid_agent):
        """Concurrent token generation must produce unique jtis."""
        import threading

        tokens = []
        lock = threading.Lock()

        def generate():
            token = auth_manager.create_token(valid_agent)
            with lock:
                tokens.append(token)

        threads = [threading.Thread(target=generate) for _ in range(20)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        jtis = set()
        for token in tokens:
            payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
            jtis.add(payload["jti"])
        assert len(jtis) == len(tokens)


